<!-- ====== HEADER / NAVBAR ====== -->
<header>
    <div class="container">
        <div class="nav">
            <div class="logo">
                CS:GO <span>Fan Hub</span>
            </div>

            <div class="nav-toggle" id="navToggle">
                <span></span>
                <span></span>
                <span></span>
            </div>

            <nav>
                <ul id="navMenu">
                    <li><a href="#hero">Home</a></li>
                    <li><a href="#about">What is CS:GO?</a></li>
                    <li><a href="#maps">Maps</a></li>
                    <li><a href="#weapons">Weapons</a></li>
                    <li><a href="#news">News</a></li>
                    <li><a href="#gallery">Gallery</a></li>
                    <li><a href="#join">Join</a></li>
                </ul>
            </nav>
        </div>
    </div>
</header>

<!-- ====== HERO ====== -->
<section class="hero" id="hero">
    <div class="container hero-content">
        <h1><span>Counter‑Strike:</span> Global Offensive</h1>
        <p>
            The ultimate tactical FPS where precision, teamwork, and strategy decide every round.
            Explore maps, master weapons, and follow the latest updates from the CS:GO universe.
        </p>
        <div class="hero-buttons">
            <a href="#maps" class="btn btn-primary">Explore Maps</a>
            <a href="#weapons" class="btn btn-outline">View Weapons</a>
            <a href="#join" class="btn btn-outline">Join Our Community</a>
        </div>
    </div>
</section>

<!-- ====== ABOUT ====== -->
<section id="about">
    <div class="container">
        <h2 class="section-title">What is CS:GO?</h2>
        <p class="section-subtitle">
            Counter‑Strike: Global Offensive (CS:GO) is a team‑based tactical shooter where Terrorists
            and Counter‑Terrorists battle across objective‑based game modes. Each round is intense,
            rewarding both mechanical skill and smart decision‑making.
        </p>

        <div class="about-grid">
            <div>
                <h3>Core Gameplay</h3>
                <p>
                    CS:GO focuses on 5v5 competitive play, where one team defends and the other
                    attacks. Each round, players buy weapons and utility with money earned from kills,
                    plants, defuses, and round wins.
                </p>
                <ul class="about-list">
                    <li>Classic bomb defusal and hostage rescue modes</li>
                    <li>Deep economy and buy system each round</li>
                    <li>High‑skill gunplay with strong recoil patterns</li>
                    <li>Huge esports scene with global tournaments</li>
                    <li>Active workshop and custom community servers</li>
                </ul>
            </div>
            <div>
                <h3>Roles & Teamplay</h3>
                <p>
                    Successful teams use defined roles and clear communication. Some common roles:
                </p>
                <ul class="about-list">
                    <li><strong>Entry Fragger:</strong> Leads attacks and takes first contact.</li>
                    <li><strong>AWPer:</strong> Dedicated sniper, holds long angles.</li>
                    <li><strong>Support:</strong> Uses utility to set up teammates.</li>
                    <li><strong>IGL:</strong> In‑game leader calling strategies.</li>
                    <li><strong>Lurker:</strong> Plays away from the team, finds picks.</li>
                </ul>
            </div>
        </div>
    </div>
</section>

<!-- ====== MAPS ====== -->
<section id="maps">
    <div class="container">
        <h2 class="section-title">Active Duty Maps</h2>
        <p class="section-subtitle">
            Learn the current competitive map pool. Each map has its own callouts, timings,
            and strategies that separate beginners from veterans.
        </p>

        <div class="cards">
            <!-- Dust II -->
            <article class="card">
                <img src="https://images.pexels.com/photos/907232/pexels-photo-907232.jpeg?auto=compress&cs=tinysrgb&w=1600"
                     alt="Dust II Map">
                <div class="card-body">
                    <h3 class="card-title">Dust II</h3>
                    <p class="card-text">
                        One of the most iconic maps in Counter‑Strike history. Simple layout with
                        long sightlines and fast mid control.
                    </p>
                    <span class="tag">Classic</span>
                </div>
            </article>

            <!-- Mirage -->
            <article class="card">
                <img src="https://images.pexels.com/photos/907231/pexels-photo-907231.jpeg?auto=compress&cs=tinysrgb&w=1600"
                     alt="Mirage Map">
                <div class="card-body">
                    <h3 class="card-title">Mirage</h3>
                    <p class="card-text">
                        A balanced map with heavy focus on mid control, executes onto A and B,
                        and strong opportunities for lurks.
                    </p>
                    <span class="tag">Balanced</span>
                </div>
            </article>

            <!-- Inferno -->
            <article class="card">
                <img src="https://images.pexels.com/photos/907225/pexels-photo-907225.jpeg?auto=compress&cs=tinysrgb&w=1600"
                     alt="Inferno Map">
                <div class="card-body">
                    <h3 class="card-title">Inferno</h3>
                    <p class="card-text">
                        Tight chokepoints, crucial banana control, and intense site retakes
                        define this map.
                    </p>
                    <span class="tag">Tactical</span>
                </div>
            </article>

            <!-- Nuke -->
            <article class="card">
                <img src="https://images.pexels.com/photos/907226/pexels-photo-907226.jpeg?auto=compress&cs=tinysrgb&w=1600"
                     alt="Nuke Map">
                <div class="card-body">
                    <h3 class="card-title">Nuke</h3>
                    <p class="card-text">
                        Vertical layout with upper and lower bombsites. Demands strong utility
                        and rotations.
                    </p>
                    <span class="tag">Complex</span>
                </div>
            </article>

            <!-- Overpass -->
            <article class="card">
                <img src="https://images.pexels.com/photos/907227/pexels-photo-907227.jpeg?auto=compress&cs=tinysrgb&w=1600"
                     alt="Overpass Map">
                <div class="card-body">
                    <h3 class="card-title">Overpass</h3>
                    <p class="card-text">
                        Large, CT‑sided map with long‑range duels, fast B hits, and slow map control
                        around A.
                    </p>
                    <span class="tag">Strategic</span>
                </div>
            </article>

