        /* ====== CONTACT / JOIN ====== */
        .contact-grid {
            display: grid;
            grid-template-columns: 3fr 2fr;
            gap: 2rem;
            align-items: flex-start;
        }

        @media (max-width: 900px) {
            .contact-grid {
                grid-template-columns: 1fr;
