        .contact-info p {
            margin-bottom: 0.4rem;
        }

        .contact-info strong {
            color: #ffcc00;
        }

        /* ====== FOOTER ====== */
        footer {
            background-color: #000;
            border-top: 1px solid #222;
            padding: 1.5rem 0;
            font-size: 0.8rem;
            color: #999;
        }

        .footer-flex {
            display: flex;
